def materialize(directory: Path) -> Path:
    directory.mkdir(parents=True, exist_ok=True)
    target = directory / "index.html"
    if target.is_file() and hashlib.sha256(target.read_bytes()).hexdigest() == DOCUMENT_SHA256:
        return target
    data = gzip.decompress(base64.b64decode(DOCUMENT, validate=True))
    if hashlib.sha256(data).hexdigest() != DOCUMENT_SHA256:
        raise ValueError("Embedded application failed the integrity check.")
    with tempfile.NamedTemporaryFile(dir=directory, delete=False) as output:
        temporary = Path(output.name)
        try:
            output.write(data)
        except BaseException:
            output.close()
            temporary.unlink(missing_ok=True)
            raise
    try:
        os.replace(temporary, target)
    finally:
        temporary.unlink(missing_ok=True)
    return target



def check_preview(path: Path) -> int:
    """Verify the embedded document and compare preview allowing only CRLF conversion."""
    try:
        embedded = gzip.decompress(base64.b64decode(DOCUMENT, validate=True))
        if hashlib.sha256(embedded).hexdigest() != DOCUMENT_SHA256:
            raise ValueError('Embedded document integrity check failed.')
        preview = path.read_bytes()
    except (OSError, ValueError, EOFError) as error:
        print('ERROR: Unable to check the application documents:', error, file=sys.stderr)
        return 1
    if preview == embedded:
        print('Desktop and HTML match exactly.')
        return 0
    # Git for Windows may check out the generated text with CRLF line endings.
    # No other modification (including BOM or content edits) is ignored.
    if preview.replace(b'\r\n', b'\n') == embedded:
        print('Desktop and HTML match after Windows line-ending normalization.')
        return 0
    print('ERROR: HTML and desktop contain different content.', file=sys.stderr)
    print('Use files from the same release, or rebuild with:', file=sys.stderr)
    print('  build-marja\\portable-venv\\Scripts\\python.exe tools\\build_language.py', file=sys.stderr)
    print('The rebuild requires VERSION, the original distribution HTML, and the tools folder.', file=sys.stderr)
    return 1

def main() -> int:
    from PyQt6.QtCore import QStandardPaths, QTimer, QUrl
    from PyQt6.QtWidgets import QApplication, QFileDialog, QMainWindow, QMessageBox
    from PyQt6.QtGui import QAction
    from live_capture import open_capture_dialog
    from PyQt6.QtWebEngineWidgets import QWebEngineView
    from PyQt6.QtWebEngineCore import QWebEnginePage

    smoke = "--smoke-test" in sys.argv[1:]
    app = QApplication([sys.argv[0]])
    app.setOrganizationName("Marja")
    app.setApplicationName("MarjaCAN")
    root = Path(QStandardPaths.writableLocation(QStandardPaths.StandardLocation.AppLocalDataLocation))
    window = QMainWindow()
    window.setWindowTitle("CAN Log Explorer · بررسی لاگ شبکه CAN · " + APP_VERSION)
    toolbar = window.addToolBar("Capture / ضبط")
    capture_action = QAction("Live capture / ضبط زنده", window)
    toolbar.addAction(capture_action)
    try:
        page_path = materialize(root / "app")
    except (OSError, ValueError) as error:
        if not smoke:
            QMessageBox.critical(window, "بررسی لاگ شبکه CAN", str(error))
        return 1
    view = QWebEngineView(window)

    class ApplicationPage(QWebEnginePage):
        def acceptNavigationRequest(self, url, navigation_type, is_main_frame):
            if url.scheme() == 'marja' and url.host() == 'capture' and is_main_frame and self.url().scheme() == 'file':
                QTimer.singleShot(0, start_capture)
                return False
            return super().acceptNavigationRequest(url, navigation_type, is_main_frame)

    view.setPage(ApplicationPage(view))
    window.setCentralWidget(view)
    window.resize(1250, 820)

    def import_capture(path, language):
        # Each callback sends the next small chunk to Chromium; no giant IPC message.
        # Very large recordings can still be imported through the ordinary file chooser.
        try:
            size = path.stat().st_size
            if size < 1 or size > 64 * 1024 * 1024:
                raise ValueError('The log is empty or exceeds 64 MiB. Use Add files to open it.' if language != 'fa' else 'فایل خالی است یا از ۶۴ مگابایت بیشتر است. آن را از بخش افزودن فایل باز کنید.')
            stream = path.open('rb')
        except (OSError, ValueError) as error:
            QMessageBox.warning(window, 'Open capture / باز کردن ضبط', str(error))
            return

        def failed():
            stream.close()
            QMessageBox.warning(window, 'Open capture / باز کردن ضبط',
                'Could not transfer the recording. Open the saved .log with Add files.' if language != 'fa' else 'انتقال ضبط انجام نشد. فایل .log ذخیره‌شده را از بخش افزودن فایل باز کنید.')

        def send_next(ok):
            if ok is not True:
                failed(); return
            try:
                chunk = stream.read(128 * 1024)
            except OSError:
                failed(); return
            if not chunk:
                stream.close()
                view.page().runJavaScript('void window.CANImport.finish()')
                return
            encoded = base64.b64encode(chunk).decode('ascii')
            view.page().runJavaScript('window.CANImport && window.CANImport.append(' + json.dumps(encoded) + ')', 0, send_next)

        call = 'window.CANImport && window.CANImport.begin(' + json.dumps(path.name) + ',' + str(size) + ')'
        view.page().runJavaScript(call, 0, send_next)

    def start_capture():
        def show_dialog(language):
            chosen_language = 'fa' if language == 'fa' else 'en'
            result = open_capture_dialog(window, chosen_language)
            if not result:
                return
            path, selected_language = result
            script = 'if(document.documentElement.lang !== ' + json.dumps(selected_language) + ') document.querySelector(".language-switch").click()'
            view.page().runJavaScript(script)
            if path:
                import_capture(path, selected_language)
        view.page().runJavaScript("document.documentElement.lang", 0, show_dialog)

    capture_action.triggered.connect(start_capture)

    def save_download(item):
        path, _ = QFileDialog.getSaveFileName(window, "ذخیرهٔ فایل", item.downloadFileName())
        if path:
            destination = Path(path)
            item.setDownloadDirectory(str(destination.parent))
            item.setDownloadFileName(destination.name)
            item.accept()
        else:
            item.cancel()

    def loaded(ok):
        if ok:
            view.page().runJavaScript("window.CANDesktop = true; window.dispatchEvent(new Event('can-desktop-ready'))")
        if smoke:
            if not ok:
                app.exit(2)
                return
            check_ready()

        elif not ok:
            QMessageBox.critical(window, "بررسی لاگ شبکه CAN", "بارگذاری برنامه انجام نشد.")

    def check_ready():
        view.page().runJavaScript(
            "['logs','walkNext','leftRun','rightRun','framesAdd'].every(id => "
            "document.getElementById(id)) && typeof document.getElementById('logs').onchange === 'function'",
            0,
            lambda ready: app.exit(0) if ready is True else QTimer.singleShot(100, check_ready),
        )

    view.page().profile().downloadRequested.connect(save_download)
    view.loadFinished.connect(loaded)
    if smoke:
        QTimer.singleShot(45000, lambda: app.exit(4))
    else:
        window.show()
    view.load(QUrl.fromLocalFile(str(page_path)))
    return app.exec()


if __name__ == "__main__":
    if len(sys.argv) == 3 and sys.argv[1] == '--check-preview':
        sys.exit(check_preview(Path(sys.argv[2])))
    sys.exit(main())
